775	    #[inline]
776	    fn point_in_triangle(&self, a: usize, b: usize, c: usize, p: usize) -> bool {
777	        point_in_triangle(
778	            self.nodes[a].x,
779	            self.nodes[a].y,
780	            self.nodes[b].x,
781	            self.nodes[b].y,
782	            self.nodes[c].x,
783	            self.nodes[c].y,
784	            self.nodes[p].x,
785	            self.nodes[p].y,
786	        )
787	    }
