// Shared geometry + RNG + generators for the earcut property harness.
#![allow(dead_code)]

pub type Pt = [f64; 2];

// ------------------------------------------------------------------ RNG
pub struct Lcg(pub u64);

impl Lcg {
    pub fn new(seed: u64) -> Lcg {
        Lcg(seed ^ 0x9E37_79B9_7F4A_7C15)
    }
    pub fn next_u64(&mut self) -> u64 {
        // 64-bit LCG (Knuth/PCG constants) + xorshift-multiply finaliser.
        self.0 = self
            .0
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        let mut x = self.0;
        x ^= x >> 33;
        x = x.wrapping_mul(0xff51afd7ed558ccd);
        x ^= x >> 33;
        x = x.wrapping_mul(0xc4ceb9fe1a85ec53);
        x ^= x >> 33;
        x
    }
    pub fn unit(&mut self) -> f64 {
        (self.next_u64() >> 11) as f64 / ((1u64 << 53) as f64)
    }
    pub fn range(&mut self, a: f64, b: f64) -> f64 {
        a + (b - a) * self.unit()
    }
    pub fn below(&mut self, n: usize) -> usize {
        (self.next_u64() % (n as u64)) as usize
    }
    pub fn between(&mut self, a: usize, b: usize) -> usize {
        a + self.below(b - a + 1)
    }
    pub fn flip(&mut self) -> bool {
        self.next_u64() & 1 == 1
    }
    /// Coordinate snapped to a coarse grid, so exact ties / collinearity show up.
    pub fn snapped(&mut self, a: f64, b: f64, step: f64) -> f64 {
        let v = self.range(a, b);
        (v / step).round() * step
    }
}

// ------------------------------------------------------------------ basic geometry
pub fn shoelace(r: &[Pt]) -> f64 {
    if r.len() < 3 {
        return 0.0;
    }
    let mut s = 0.0;
    for i in 0..r.len() {
        let j = (i + 1) % r.len();
        s += r[i][0] * r[j][1] - r[j][0] * r[i][1];
    }
    s / 2.0
}

pub fn tri_area(a: Pt, b: Pt, c: Pt) -> f64 {
    ((b[0] - a[0]) * (c[1] - a[1]) - (c[0] - a[0]) * (b[1] - a[1])) / 2.0
}

pub fn cross3(a: Pt, b: Pt, c: Pt) -> f64 {
    (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
}

pub fn orient(a: Pt, b: Pt, c: Pt, eps: f64) -> i32 {
    let v = cross3(a, b, c);
    if v > eps {
        1
    } else if v < -eps {
        -1
    } else {
        0
    }
}

fn on_seg(a: Pt, b: Pt, c: Pt) -> bool {
    // c is (approximately) collinear with a-b; is it within the bbox?
    c[0] <= a[0].max(b[0]) && c[0] >= a[0].min(b[0]) && c[1] <= a[1].max(b[1]) && c[1] >= a[1].min(b[1])
}

/// Do the closed segments a-b and c-d intersect?
pub fn segs_intersect(a: Pt, b: Pt, c: Pt, d: Pt, eps: f64) -> bool {
    let o1 = orient(a, b, c, eps);
    let o2 = orient(a, b, d, eps);
    let o3 = orient(c, d, a, eps);
    let o4 = orient(c, d, b, eps);
    if o1 != o2 && o3 != o4 {
        return true;
    }
    if o1 == 0 && on_seg(a, b, c) {
        return true;
    }
    if o2 == 0 && on_seg(a, b, d) {
        return true;
    }
    if o3 == 0 && on_seg(c, d, a) {
        return true;
    }
    if o4 == 0 && on_seg(c, d, b) {
        return true;
    }
    false
}

/// Crossing-number point-in-ring test (boundary result unspecified).
pub fn point_in_ring(r: &[Pt], p: Pt) -> bool {
    let mut inside = false;
    let n = r.len();
    for i in 0..n {
        let j = (i + n - 1) % n;
        let (xi, yi) = (r[i][0], r[i][1]);
        let (xj, yj) = (r[j][0], r[j][1]);
        if ((yi > p[1]) != (yj > p[1])) && (p[0] < (xj - xi) * (p[1] - yi) / (yj - yi) + xi) {
            inside = !inside;
        }
    }
    inside
}

pub fn bbox(rings: &[Vec<Pt>]) -> (f64, f64, f64, f64) {
    let mut r = (f64::INFINITY, f64::INFINITY, f64::NEG_INFINITY, f64::NEG_INFINITY);
    for ring in rings {
        for p in ring {
            r.0 = r.0.min(p[0]);
            r.1 = r.1.min(p[1]);
            r.2 = r.2.max(p[0]);
            r.3 = r.3.max(p[1]);
        }
    }
    r
}

// ------------------------------------------------------------------ convex clipping (overlap area)
fn clip_half(poly: &[Pt], a: Pt, b: Pt) -> Vec<Pt> {
    // keep the side with cross3(a,b,p) >= 0
    let mut out: Vec<Pt> = Vec::with_capacity(poly.len() + 2);
    let n = poly.len();
    if n == 0 {
        return out;
    }
    for i in 0..n {
        let cur = poly[i];
        let nxt = poly[(i + 1) % n];
        let dc = cross3(a, b, cur);
        let dn = cross3(a, b, nxt);
        if dc >= 0.0 {
            out.push(cur);
        }
        if (dc > 0.0 && dn < 0.0) || (dc < 0.0 && dn > 0.0) {
            let t = dc / (dc - dn);
            out.push([cur[0] + t * (nxt[0] - cur[0]), cur[1] + t * (nxt[1] - cur[1])]);
        }
    }
    out
}

/// |area| of the intersection of two triangles.
pub fn tri_overlap_area(t1: &[Pt; 3], t2: &[Pt; 3]) -> f64 {
    // orient t2 counter-clockwise so the "keep >= 0" side is the interior
    let mut q = *t2;
    if tri_area(q[0], q[1], q[2]) < 0.0 {
        q.swap(1, 2);
    }
    let mut poly: Vec<Pt> = t1.to_vec();
    if tri_area(poly[0], poly[1], poly[2]) < 0.0 {
        poly.swap(1, 2);
    }
    for i in 0..3 {
        poly = clip_half(&poly, q[i], q[(i + 1) % 3]);
        if poly.len() < 3 {
            return 0.0;
        }
    }
    shoelace(&poly).abs()
}

// ------------------------------------------------------------------ case classification
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Class {
    /// any ring has < 3 vertices, duplicate consecutive vertices,
    /// exactly-collinear consecutive triple, or self-intersects
    pub ring_degenerate: bool,
    /// near-collinear (not exactly zero) triple somewhere
    pub near_collinear: bool,
    /// holes are strictly inside the outer ring and pairwise disjoint
    pub holes_nested: bool,
}

impl Class {
    /// Clean simple polygon, no holes: strongest guarantees apply.
    pub fn clean_simple(&self, nholes: usize) -> bool {
        nholes == 0 && !self.ring_degenerate && !self.near_collinear
    }
    /// Clean polygon with properly nested holes.
    pub fn clean_holed(&self, nholes: usize) -> bool {
        nholes > 0 && !self.ring_degenerate && !self.near_collinear && self.holes_nested
    }
}

pub fn classify(rings: &[Vec<Pt>]) -> Class {
    let (x0, y0, x1, y1) = bbox(rings);
    let scale = ((x1 - x0).abs()).max((y1 - y0).abs()).max(1e-30);
    let eps = 1e-12 * scale * scale;
    let near_eps = 1e-7 * scale * scale;

    let mut ring_degenerate = false;
    let mut near_collinear = false;

    for ring in rings {
        let n = ring.len();
        if n < 3 {
            ring_degenerate = true;
            continue;
        }
        if shoelace(ring) == 0.0 {
            ring_degenerate = true;
        }
        for i in 0..n {
            let a = ring[(i + n - 1) % n];
            let b = ring[i];
            let c = ring[(i + 1) % n];
            if b == a || b == c {
                ring_degenerate = true;
            }
            let cr = cross3(a, b, c);
            if cr == 0.0 {
                ring_degenerate = true;
            } else if cr.abs() < near_eps {
                near_collinear = true;
            }
            let _ = eps;
        }
        // self intersection of non-adjacent edges
        'outer: for i in 0..n {
            for j in (i + 1)..n {
                if j == i || (j + 1) % n == i || (i + 1) % n == j {
                    continue;
                }
                if segs_intersect(ring[i], ring[(i + 1) % n], ring[j], ring[(j + 1) % n], 0.0) {
                    ring_degenerate = true;
                    break 'outer;
                }
            }
        }
    }

    // nesting / disjointness of holes
    let mut holes_nested = true;
    if rings.len() > 1 {
        if rings[0].len() < 3 {
            holes_nested = false;
        }
        for h in 1..rings.len() {
            if rings[h].len() < 3 {
                holes_nested = false;
                break;
            }
            for p in &rings[h] {
                if !point_in_ring(&rings[0], *p) {
                    holes_nested = false;
                }
            }
            // hole edges must not touch the outer boundary
            let hn = rings[h].len();
            let on = rings[0].len();
            for i in 0..hn {
                for j in 0..on {
                    if segs_intersect(
                        rings[h][i],
                        rings[h][(i + 1) % hn],
                        rings[0][j],
                        rings[0][(j + 1) % on],
                        0.0,
                    ) {
                        holes_nested = false;
                    }
                }
            }
            for k in (h + 1)..rings.len() {
                let kn = rings[k].len();
                if kn < 3 {
                    continue;
                }
                for p in &rings[k] {
                    if point_in_ring(&rings[h], *p) {
                        holes_nested = false;
                    }
                }
                for p in &rings[h] {
                    if point_in_ring(&rings[k], *p) {
                        holes_nested = false;
                    }
                }
                for i in 0..hn {
                    for j in 0..kn {
                        if segs_intersect(
                            rings[h][i],
                            rings[h][(i + 1) % hn],
                            rings[k][j],
                            rings[k][(j + 1) % kn],
                            0.0,
                        ) {
                            holes_nested = false;
                        }
                    }
                }
            }
        }
    }

    Class {
        ring_degenerate,
        near_collinear,
        holes_nested,
    }
}

// ------------------------------------------------------------------ generators
pub struct Case {
    pub id: usize,
    pub family: &'static str,
    pub rings: Vec<Vec<Pt>>,
}

fn reverse_maybe(ring: &mut Vec<Pt>, rev: bool) {
    if rev {
        ring.reverse();
    }
}

/// Star-shaped (radially monotone) polygon around `c`: strictly increasing
/// angles => guaranteed simple.
fn radial(rng: &mut Lcg, c: Pt, n: usize, rmin: f64, rmax: f64, snap: Option<f64>) -> Vec<Pt> {
    let mut ring = Vec::with_capacity(n);
    for i in 0..n {
        let base = 2.0 * std::f64::consts::PI * (i as f64) / (n as f64);
        let jitter = rng.range(-0.35, 0.35) * (2.0 * std::f64::consts::PI / n as f64);
        let ang = base + jitter;
        let r = rng.range(rmin, rmax);
        let mut p = [c[0] + r * ang.cos(), c[1] + r * ang.sin()];
        if let Some(s) = snap {
            p = [(p[0] / s).round() * s, (p[1] / s).round() * s];
        }
        ring.push(p);
    }
    ring
}

fn regular(c: Pt, n: usize, r: f64, phase: f64) -> Vec<Pt> {
    (0..n)
        .map(|i| {
            let a = phase + 2.0 * std::f64::consts::PI * (i as f64) / (n as f64);
            [c[0] + r * a.cos(), c[1] + r * a.sin()]
        })
        .collect()
}

fn star(c: Pt, spikes: usize, r_in: f64, r_out: f64, phase: f64) -> Vec<Pt> {
    let n = spikes * 2;
    (0..n)
        .map(|i| {
            let a = phase + 2.0 * std::f64::consts::PI * (i as f64) / (n as f64);
            let r = if i % 2 == 0 { r_out } else { r_in };
            [c[0] + r * a.cos(), c[1] + r * a.sin()]
        })
        .collect()
}

fn comb(teeth: usize, w: f64, h: f64) -> Vec<Pt> {
    // rectilinear comb, no three consecutive collinear vertices
    let mut v: Vec<Pt> = Vec::new();
    let k = teeth;
    v.push([0.0, 0.0]);
    v.push([(2 * k + 1) as f64 * w, 0.0]);
    v.push([(2 * k + 1) as f64 * w, h]);
    for j in (1..=k).rev() {
        v.push([(2 * j) as f64 * w, h]);
        v.push([(2 * j) as f64 * w, h * 0.35]);
        v.push([(2 * j - 1) as f64 * w, h * 0.35]);
        v.push([(2 * j - 1) as f64 * w, h]);
    }
    v.push([0.0, h]);
    v
}

fn spiral(turns: usize, per: usize, r0: f64, dr: f64, band: f64) -> Vec<Pt> {
    // Archimedean band: out along the spiral, back along an inner offset copy.
    let steps = turns * per;
    let mut outw: Vec<Pt> = Vec::new();
    let mut inw: Vec<Pt> = Vec::new();
    for i in 0..=steps {
        let a = 2.0 * std::f64::consts::PI * (i as f64) / (per as f64);
        let r = r0 + dr * (i as f64) / (per as f64);
        outw.push([r * a.cos(), r * a.sin()]);
        let ri = r - band;
        inw.push([ri * a.cos(), ri * a.sin()]);
    }
    inw.reverse();
    outw.extend(inw);
    outw
}

fn rect(x0: f64, y0: f64, x1: f64, y1: f64) -> Vec<Pt> {
    vec![[x0, y0], [x1, y0], [x1, y1], [x0, y1]]
}

pub fn make_case(id: usize) -> Case {
    let mut rng = Lcg::new(0x5EED_0000_0000_0000u64 ^ (id as u64).wrapping_mul(0x9E3779B1));
    // 11 families, round-robin so every family gets plenty of cases
    let fam = id % 11;
    match fam {
        0 => {
            // regular convex n-gon, both windings, some tiny / huge scales
            let n = rng.between(3, 200);
            let r = [1.0, 1e-4, 1e4, 0.3][rng.below(4)];
            let mut ring = regular([rng.range(-2.0, 2.0), rng.range(-2.0, 2.0)], n, r, rng.range(0.0, 1.0));
            reverse_maybe(&mut ring, rng.flip());
            Case { id, family: "regular-convex", rings: vec![ring] }
        }
        1 => {
            // random star-shaped simple polygon, sizes straddling the 80-vertex
            // hashing threshold
            let n = if id % 22 == 1 { rng.between(3, 40) } else { rng.between(81, 260) };
            let mut ring = radial(&mut rng, [0.0, 0.0], n, 0.4, 2.0, None);
            reverse_maybe(&mut ring, rng.flip());
            Case { id, family: "radial-simple", rings: vec![ring] }
        }
        2 => {
            // star / spiky polygon (heavily concave)
            let spikes = rng.between(3, 90);
            let r_out = 2.0;
            let r_in = rng.range(0.05, 1.4);
            let mut ring = star([0.0, 0.0], spikes, r_in, r_out, rng.range(0.0, 0.7));
            reverse_maybe(&mut ring, rng.flip());
            Case { id, family: "star", rings: vec![ring] }
        }
        3 => {
            // rectilinear comb (deeply concave, right angles, exact ties)
            let teeth = rng.between(1, 30);
            let mut ring = comb(teeth, rng.range(0.5, 2.0), rng.range(1.0, 6.0));
            reverse_maybe(&mut ring, rng.flip());
            Case { id, family: "comb", rings: vec![ring] }
        }
        4 => {
            // spiral band
            let turns = rng.between(1, 4);
            let per = rng.between(8, 40);
            let dr = rng.range(1.0, 2.0);
            let band = dr * rng.range(0.15, 0.45);
            let mut ring = spiral(turns, per, 1.0, dr, band);
            reverse_maybe(&mut ring, rng.flip());
            Case { id, family: "spiral", rings: vec![ring] }
        }
        5 => {
            // square with a grid of square holes (properly nested, disjoint)
            let g = rng.between(1, 5);
            let side = 10.0;
            let mut rings = vec![rect(0.0, 0.0, side, side)];
            let cell = side / (g as f64 + 1.0);
            for a in 0..g {
                for b in 0..g {
                    let cx = cell * (a as f64 + 1.0);
                    let cy = cell * (b as f64 + 1.0);
                    let hw = cell * rng.range(0.12, 0.4);
                    let mut h = rect(cx - hw, cy - hw, cx + hw, cy + hw);
                    h.reverse(); // holes clockwise
                    rings.push(h);
                }
            }
            if rng.flip() {
                rings[0].reverse();
            }
            Case { id, family: "square-grid-holes", rings }
        }
        6 => {
            // annulus: radial outer + scaled-down radial hole (concentric,
            // strictly nested by construction)
            let n = rng.between(20, 130);
            let outer_r0 = 3.0;
            let outer_r1 = 5.0;
            let outer = radial(&mut rng, [0.0, 0.0], n, outer_r0, outer_r1, None);
            let m = rng.between(3, 100);
            let inner = radial(&mut rng, [0.0, 0.0], m, 0.5, 2.0, None);
            let mut rings = vec![outer, inner];
            rings[1].reverse();
            if rng.flip() {
                rings[0].reverse();
            }
            Case { id, family: "annulus", rings }
        }
        7 => {
            // outer square + k convex holes, one per grid cell (disjoint)
            let k = rng.between(1, 9);
            let side = 20.0;
            let mut rings = vec![rect(0.0, 0.0, side, side)];
            let cols = 3usize;
            for i in 0..k {
                let cx = 3.5 + (i % cols) as f64 * 6.5;
                let cy = 3.5 + (i / cols) as f64 * 6.5;
                let n = rng.between(3, 24);
                let r = rng.range(0.6, 2.4);
                let mut h = regular([cx, cy], n, r, rng.range(0.0, 1.0));
                h.reverse();
                rings.push(h);
            }
            Case { id, family: "square-convex-holes", rings }
        }
        8 => {
            // big star outer with concentric star hole -> > 80 verts, hashing
            let spikes = rng.between(20, 70);
            let outer = star([0.0, 0.0], spikes, 6.0, 10.0, 0.0);
            let mut inner = star([0.0, 0.0], rng.between(3, 40), 1.0, 3.0, rng.range(0.0, 0.5));
            inner.reverse();
            Case { id, family: "star-with-star-hole", rings: vec![outer, inner] }
        }
        9 => {
            // grid-snapped radial polygon: forces exact coordinate ties and
            // exactly-collinear triples
            let n = rng.between(6, 140);
            let mut ring = radial(&mut rng, [0.0, 0.0], n, 2.0, 8.0, Some(1.0));
            ring.dedup();
            reverse_maybe(&mut ring, rng.flip());
            Case { id, family: "snapped-radial", rings: vec![ring] }
        }
        _ => degenerate_case(id, &mut rng),
    }
}

fn degenerate_case(id: usize, rng: &mut Lcg) -> Case {
    let which = (id / 11) % 16;
    match which {
        0 => Case { id, family: "deg-empty", rings: vec![] },
        1 => Case { id, family: "deg-empty-ring", rings: vec![vec![]] },
        2 => Case { id, family: "deg-1pt", rings: vec![vec![[1.0, 1.0]]] },
        3 => Case { id, family: "deg-2pt", rings: vec![vec![[0.0, 0.0], [1.0, 1.0]]] },
        4 => Case {
            id,
            family: "deg-all-same",
            rings: vec![vec![[2.0, 3.0]; rng.between(3, 12)]],
        },
        5 => {
            let n = rng.between(3, 40);
            let ring: Vec<Pt> = (0..n).map(|i| [i as f64, 2.0 * i as f64]).collect();
            Case { id, family: "deg-collinear", rings: vec![ring] }
        }
        6 => Case {
            id,
            family: "deg-bowtie",
            rings: vec![vec![[0.0, 0.0], [4.0, 4.0], [4.0, 0.0], [0.0, 4.0]]],
        },
        7 => {
            // clean polygon with every vertex duplicated
            let base = radial(rng, [0.0, 0.0], rng.between(4, 60), 1.0, 3.0, None);
            let mut ring = Vec::new();
            for p in &base {
                ring.push(*p);
                ring.push(*p);
            }
            Case { id, family: "deg-dup-verts", rings: vec![ring] }
        }
        8 => {
            // clean polygon with collinear midpoints inserted on every edge
            let base = radial(rng, [0.0, 0.0], rng.between(4, 60), 1.0, 3.0, None);
            let n = base.len();
            let mut ring = Vec::new();
            for i in 0..n {
                let a = base[i];
                let b = base[(i + 1) % n];
                ring.push(a);
                ring.push([(a[0] + b[0]) / 2.0, (a[1] + b[1]) / 2.0]);
            }
            Case { id, family: "deg-collinear-mid", rings: vec![ring] }
        }
        9 => {
            // hole strictly larger than the outer ring (the test10.cpp shape)
            let outer = regular([0.0, 0.0], rng.between(3, 12), 1.0, 0.0);
            let mut inner = regular([0.0, 0.0], rng.between(3, 12), 3.0, 0.0);
            inner.reverse();
            Case { id, family: "deg-hole-bigger", rings: vec![outer, inner] }
        }
        10 => {
            // two overlapping holes
            let outer = rect(0.0, 0.0, 10.0, 10.0);
            let mut h1 = rect(2.0, 2.0, 6.0, 6.0);
            let mut h2 = rect(4.0, 4.0, 8.0, 8.0);
            h1.reverse();
            h2.reverse();
            Case { id, family: "deg-overlap-holes", rings: vec![outer, h1, h2] }
        }
        11 => {
            // hole touching the outer boundary exactly (bridge x == hx path)
            let outer = rect(0.0, 0.0, 10.0, 10.0);
            let y = rng.snapped(1.0, 9.0, 1.0);
            let mut h = vec![[0.0, y], [4.0, y - 1.0], [4.0, y + 1.0]];
            h.reverse();
            Case { id, family: "deg-hole-touching", rings: vec![outer, h] }
        }
        12 => {
            // many degenerate holes: single points / two-point rings (steiner)
            let outer = rect(0.0, 0.0, 10.0, 10.0);
            let mut rings = vec![outer];
            for i in 0..rng.between(1, 6) {
                rings.push(vec![[1.0 + i as f64, 5.0]]);
            }
            rings.push(vec![[3.0, 3.0], [3.5, 3.5]]);
            Case { id, family: "deg-point-holes", rings }
        }
        13 => {
            // zero-area sliver spikes appended to a clean polygon
            let mut ring = radial(rng, [0.0, 0.0], rng.between(5, 50), 1.0, 3.0, None);
            let k = ring.len();
            let p = ring[0];
            ring.insert(1, [p[0] * 1.5, p[1] * 1.5]);
            ring.insert(2, p);
            let _ = k;
            Case { id, family: "deg-spike", rings: vec![ring] }
        }
        14 => {
            // self-intersecting radial-ish polygon (shuffled vertex order)
            let mut ring = radial(rng, [0.0, 0.0], rng.between(6, 120), 1.0, 3.0, None);
            let n = ring.len();
            for i in 0..n {
                let j = rng.below(n);
                ring.swap(i, j);
            }
            Case { id, family: "deg-shuffled", rings: vec![ring] }
        }
        _ => {
            // huge coordinate magnitudes + subnormal-ish deltas
            let s = [1e12, 1e-12, 1e8][rng.below(3)];
            let mut ring = radial(rng, [s, -s], rng.between(3, 100), s * 0.1, s * 0.5, None);
            reverse_maybe(&mut ring, rng.flip());
            Case { id, family: "deg-extreme-scale", rings: vec![ring] }
        }
    }
}
